<div class="space-y-6"><div><p class="text-xs font-semibold uppercase tracking-[0.2em] text-slate-500">Website CMS</p><h2 class="mt-1 text-2xl font-bold text-slate-900">Website settings</h2><p class="mt-1 text-sm text-slate-600">Manage the public site identity, contact details, social links, and brand palette.</p></div><form wire:submit="save" class="grid gap-6 lg:grid-cols-2"><section class="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><h3 class="text-lg font-semibold">Identity and contact</h3><div class="mt-5 space-y-4"><div><label class="text-sm font-medium">Site name</label><input wire:model.blur="siteName" class="mt-1 w-full rounded-lg border-slate-300"></div><div><label class="text-sm font-medium">Tagline</label><input wire:model.blur="tagline" class="mt-1 w-full rounded-lg border-slate-300"></div><div><label class="text-sm font-medium">Logo</label><input wire:model="logo" type="file" accept="image/png,image/jpeg,image/webp" class="mt-1 w-full rounded-lg border-slate-300"></div><div><label class="text-sm font-medium">Email</label><input wire:model.blur="email" type="email" class="mt-1 w-full rounded-lg border-slate-300"></div><div><label class="text-sm font-medium">Phone</label><input wire:model.blur="phone" class="mt-1 w-full rounded-lg border-slate-300"></div><div><label class="text-sm font-medium">Address</label><textarea wire:model.blur="address" rows="3" class="mt-1 w-full rounded-lg border-slate-300"></textarea></div></div></section><section class="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><h3 class="text-lg font-semibold">Brand and social links</h3><div class="mt-5 space-y-4"><div class="grid grid-cols-3 gap-3"><label class="text-sm">Primary<input wire:model.blur="primaryColor" type="color" class="mt-1 h-10 w-full rounded"></label><label class="text-sm">Secondary<input wire:model.blur="secondaryColor" type="color" class="mt-1 h-10 w-full rounded"></label><label class="text-sm">Accent<input wire:model.blur="accentColor" type="color" class="mt-1 h-10 w-full rounded"></label></div><div><label class="text-sm font-medium">Facebook</label><input wire:model.blur="facebook" type="url" class="mt-1 w-full rounded-lg border-slate-300"></div><div><label class="text-sm font-medium">Instagram</label><input wire:model.blur="instagram" type="url" class="mt-1 w-full rounded-lg border-slate-300"></div><div><label class="text-sm font-medium">YouTube</label><input wire:model.blur="youtube" type="url" class="mt-1 w-full rounded-lg border-slate-300"></div></div></section><div class="flex justify-end lg:col-span-2"><x-button type="submit" icon="save" target="save" :loading="true">Save website settings</x-button></div></form></div>
